@js:
a = src.match(/"url":"(.*)","url\_next/)[1]
if(a.match(/ACG\-/)){
	url="https://jx.1313.top/player/?url="+a
	}else if(a.match(/dm\d+/)){
	url="https://jx.cilicili.one/player/?url="+a
		}else{
	url=a
		}
if(book.durChapterIndex == chapter.index){
java.startBrowser(url,chapter.title);
java.toast('正在加载视频...');
result = ' \n\n【刷新正文】跳转播放\n不要相信且不要点击视频里的任何广告，误触后请立即返回\n🔗直链:\n' + url}

